from __future__ import annotations

from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]
FOCUS = ROOT / "cloud_api" / "aster_strategy2_focus_v2.py"
TEST = ROOT / "cloud_api" / "tests" / "test_focus_v2_fast_recovery.py"

text = FOCUS.read_text(encoding="utf-8")
original = text

text = text.replace(
    'REHEDGE_PREFIX="s2fv2rh-"\n',
    'REHEDGE_PREFIX="s2fv2rh-"\nRECOVERY_MODEL_FAST=2\nRECOVERY_STAGE_PROGRESS=(0.22,0.48,0.72,0.95)\n',
)

text = text.replace(
    '    dca_anchor_price:float=0.0; last_action:str="IDLE"; last_reason:str=""\n',
    '    dca_anchor_price:float=0.0; last_action:str="IDLE"; last_reason:str=""\n'
    '    recovery_model_version:int=1; released_short_qty:float=0.0; armed_rehedge_qty:float=0.0\n'
    '    last_release_price:float=0.0; next_release_price:float=0.0; recovery_progress_ratio:float=0.0; last_rehedge_price:float=0.0\n'
    '    rehedge_client_ids:tuple[str,...]=()\n',
)

state_block = '''def state_from(raw:Any)->FocusV2State:\n    x=raw if isinstance(raw,dict) else {}\n    def g(c,s,d=None):return x[c] if c in x else x.get(s,d)\n    ids=g("rehedgeClientIds","rehedge_client_ids",())\n    if not isinstance(ids,(list,tuple)):ids=()\n    return FocusV2State(\n        cycle_id=str(g("cycleId","cycle_id","") or ""),symbol=str(g("symbol","symbol","") or "").upper(),\n        cycle_start_equity=f(g("cycleStartEquity","cycle_start_equity",0)),opened_at_ms=int(f(g("openedAt","opened_at_ms",0))),\n        original_entry=f(g("originalEntry","original_entry",0)),weighted_entry=f(g("weightedEntry","weighted_entry",0)),dca_count=int(f(g("dcaCount","dca_count",0))),\n        recent_low=f(g("recentLow","recent_low",0)),recovery_high=f(g("recoveryHigh","recovery_high",0)),release_stage=int(f(g("releaseStage","release_stage",0))),\n        rehedge_client_id=str(g("rehedgeClientId","rehedge_client_id","") or ""),rehedge_stop_price=f(g("rehedgeStopPrice","rehedge_stop_price",0)),\n        realized_hedge_pnl=f(g("realizedHedgePnl","realized_hedge_pnl",0)),harvest_baseline_equity=f(g("harvestBaselineEquity","harvest_baseline_equity",g("cycleStartEquity","cycle_start_equity",0))),\n        total_harvested_profit=f(g("totalHarvestedProfit","total_harvested_profit",0)),last_harvest_profit=f(g("lastHarvestProfit","last_harvest_profit",0)),\n        dca_anchor_price=f(g("dcaAnchorPrice","dca_anchor_price",g("weightedEntry","weighted_entry",g("originalEntry","original_entry",0)))),last_action=str(g("lastAction","last_action","IDLE") or "IDLE"),last_reason=str(g("lastReason","last_reason","") or ""),\n        recovery_model_version=int(f(g("recoveryModelVersion","recovery_model_version",1),1)),released_short_qty=f(g("releasedShortQty","released_short_qty",0)),armed_rehedge_qty=f(g("armedRehedgeQty","armed_rehedge_qty",0)),\n        last_release_price=f(g("lastReleasePrice","last_release_price",0)),next_release_price=f(g("nextReleasePrice","next_release_price",0)),recovery_progress_ratio=f(g("recoveryProgressRatio","recovery_progress_ratio",0)),last_rehedge_price=f(g("lastRehedgePrice","last_rehedge_price",0)),\n        rehedge_client_ids=tuple(str(v) for v in ids if v),\n    )\n\ndef state_map(s:FocusV2State)->dict[str,Any]:\n    return {\n        "cycleId":s.cycle_id,"symbol":s.symbol,"cycleStartEquity":s.cycle_start_equity,"openedAt":s.opened_at_ms,"originalEntry":s.original_entry,"weightedEntry":s.weighted_entry,"dcaCount":s.dca_count,\n        "recentLow":s.recent_low,"recoveryHigh":s.recovery_high,"releaseStage":s.release_stage,"rehedgeClientId":s.rehedge_client_id,"rehedgeClientIds":list(s.rehedge_client_ids),"rehedgeStopPrice":s.rehedge_stop_price,\n        "realizedHedgePnl":s.realized_hedge_pnl,"harvestBaselineEquity":s.harvest_baseline_equity,"totalHarvestedProfit":s.total_harvested_profit,"lastHarvestProfit":s.last_harvest_profit,"dcaAnchorPrice":s.dca_anchor_price,\n        "lastAction":s.last_action,"lastReason":s.last_reason,"recoveryModelVersion":s.recovery_model_version,"releasedShortQty":s.released_short_qty,"armedRehedgeQty":s.armed_rehedge_qty,\n        "lastReleasePrice":s.last_release_price,"nextReleasePrice":s.next_release_price,"recoveryProgressRatio":s.recovery_progress_ratio,"lastRehedgePrice":s.last_rehedge_price,\n    }\n\ndef recovery_progress(mark:float,recent_low:float,long_break_even:float)->float:\n    if mark<=0 or recent_low<=0:return 0.0\n    if long_break_even<=recent_low:return 1.0 if mark>=long_break_even>0 else 0.0\n    return max(0.0,(mark-recent_low)/(long_break_even-recent_low))\n\ndef recovery_stage_for_progress(progress:float)->int:\n    stage=0\n    for idx,threshold in enumerate(RECOVERY_STAGE_PROGRESS,1):\n        if progress+1e-12>=threshold:stage=idx\n    return stage\n\ndef recovery_remaining_ratio(stage:int,release_ratio:float)->float:\n    if stage>=4:return 0.0\n    return (1-max(0.0,min(1.0,release_ratio)))**max(0,stage)\n\ndef recovery_stage_price(recent_low:float,long_break_even:float,stage:int)->float:\n    if recent_low<=0 or long_break_even<=recent_low or stage<1 or stage>len(RECOVERY_STAGE_PROGRESS):return 0.0\n    return recent_low+(long_break_even-recent_low)*RECOVERY_STAGE_PROGRESS[stage-1]\n\ndef target_hedge_notional'''
text, n = re.subn(r'def state_from\(raw:Any\)->FocusV2State:.*?\ndef target_hedge_notional', state_block, text, flags=re.S)
assert n == 1, f"state block replacements={n}"

order_block = '''def _rehedge_ids(state:FocusV2State)->tuple[str,...]:\n    return tuple(dict.fromkeys((*state.rehedge_client_ids,*((state.rehedge_client_id,) if state.rehedge_client_id else ()))))\n\ndef _cancel_rehedge(client:Any,state:FocusV2State)->None:\n    if not state.symbol:return\n    for cid in _rehedge_ids(state):\n        try:client.cancel_order(state.symbol,client_order_id=cid)\n        except Exception:pass\n\ndef _open_rehedge_qty(open_orders:list[dict[str,Any]]|None,symbol:str)->float:\n    total=0.0\n    for o in open_orders or []:\n        if isinstance(o,dict) and str(o.get("symbol","")).upper()==symbol.upper() and str(o.get("clientOrderId","")).startswith(REHEDGE_PREFIX):\n            total+=abs(f(o.get("origQty",o.get("quantity"))))\n    return total\n\ndef _arm_rehedge(*,client:Any,state:FocusV2State,settings:Strategy2Config,mark:float,quantity:float,reserve_order:Callable|None)->FocusV2State:\n    from dataclasses import replace\n    if quantity<=0:return state\n    stop=rehedge_stop(mark,settings.focus_v2_rehedge_setback_pct)\n    cid=(REHEDGE_PREFIX+hashlib.sha256(f"{state.cycle_id}|{state.release_stage}|{stop:.8f}|{quantity:.8f}".encode()).hexdigest()[:20])[:36]\n    if cid in _rehedge_ids(state):return state\n    intent=AsterOrderIntent(cid,state.symbol,PositionSide.SHORT,Decimal(str(quantity)),"OPEN")\n    if reserve_order:reserve_order(intent,{"kind":"FOCUS_V2_REHEDGE_STOP","cycleId":state.cycle_id,"riskReducing":True,"marginUsd":float(quantity)*mark/max(1,settings.leverage)})\n    payload={"symbol":state.symbol,"side":"SELL","positionSide":"SHORT","type":"STOP_MARKET","quantity":format(Decimal(str(quantity)),"f"),"stopPrice":format(Decimal(str(stop)),"f"),"workingType":"MARK_PRICE","newClientOrderId":cid}\n    response=client.signed_request("POST","/fapi/v3/order",payload)\n    if not isinstance(response,dict) or response.get("orderId") is None:raise RuntimeError("Aster bevestigde Focus 2.0 re-hedge trigger niet")\n    ids=tuple(dict.fromkeys((*_rehedge_ids(state),cid)))\n    return replace(state,rehedge_client_id=cid,rehedge_client_ids=ids,rehedge_stop_price=stop,armed_rehedge_qty=state.armed_rehedge_qty+float(quantity))\n\ndef _bb5'''
text, n = re.subn(r'def _cancel_rehedge\(client:Any,state:FocusV2State\)->None:.*?\ndef _bb5', order_block, text, flags=re.S)
assert n == 1, f"rehedge block replacements={n}"

old_new_cycle = 'state=FocusV2State(cycle,symbol,equity,timestamp_ms,0,0,0,mark,mark,0,"",0,0,equity,0,0,mark,"OPEN_PENDING","nieuwe schone Focus 2.0 cycle")'
new_new_cycle = 'state=FocusV2State(cycle,symbol,equity,timestamp_ms,0,0,0,mark,mark,0,"",0,0,equity,0,0,mark,"OPEN_PENDING","nieuwe schone Focus 2.0 cycle",recovery_model_version=RECOVERY_MODEL_FAST)'
assert old_new_cycle in text
text = text.replace(old_new_cycle, new_new_cycle, 1)

# DCA protection accounts for already armed exchange-side backup exposure.
text = text.replace(
    'expected_hedge_gap=max(0.0,expected_hedge-short_notional)',
    'armed_before_dca=_open_rehedge_qty(open_orders,symbol)*mark;expected_hedge_gap=max(0.0,expected_hedge-short_notional-armed_before_dca)',
)
text = text.replace(
    'hedge_gap=max(0.0,hedge_target_after-short_notional)',
    'armed_before_dca=_open_rehedge_qty(open_orders,symbol)*p;hedge_gap=max(0.0,hedge_target_after-short_notional-armed_before_dca)',
)

marker = '    # Reconcile protective hedge to current LONG. This is why old start-size is never used.\n'
start = text.index(marker)
end = text.index('    # No recovery: make sure hedge is large enough for current LONG, unless an already-armed stop covers the released tranche.\n', start)
legacy = text[start:end]
legacy_body = legacy[len(marker):]
legacy_indented = ''.join(('    '+line if line.strip() else line) for line in legacy_body.splitlines(True))

fast = '''    # Reconcile protective hedge to current LONG. Existing cycles stay on behavior v1; new cycles use staged fast recovery.\n    hedge_target=target_hedge_notional(long_notional,min_bias_usdt=settings.focus_v2_min_net_long_usdt,min_bias_ratio=settings.focus_v2_min_net_long_ratio,max_hedge_ratio=settings.focus_v2_max_hedge_ratio)\n    if state.recovery_model_version < RECOVERY_MODEL_FAST:\n''' + legacy_indented.replace('    hedge_target=target_hedge_notional(long_notional,min_bias_usdt=settings.focus_v2_min_net_long_usdt,min_bias_ratio=settings.focus_v2_min_net_long_ratio,max_hedge_ratio=settings.focus_v2_max_hedge_ratio)\n','',1) + '''    else:\n        armed_live_qty=_open_rehedge_qty(open_orders,symbol)\n        state=replace(state,armed_rehedge_qty=armed_live_qty)\n        progress=recovery_progress(mark,state.recent_low,entry)\n        desired_stage=recovery_stage_for_progress(progress)\n        next_stage=min(4,state.release_stage+1)\n        next_price=recovery_stage_price(state.recent_low,entry,next_stage)\n        state=replace(state,recovery_progress_ratio=progress,next_release_price=next_price,recovery_high=max(state.recovery_high,mark))\n        setback_hit=state.last_release_price>0 and mark<=state.last_release_price*(1-max(0.0001,settings.focus_v2_rehedge_setback_pct))\n        tolerance=max(1.0,long_notional*.002)\n        if setback_hit and short_notional+armed_live_qty*mark>=hedge_target-tolerance:\n            state=replace(state,release_stage=0,recovery_high=mark,last_rehedge_price=mark,last_action="REHEDGE_RESTORED",last_reason="terugval heeft exchange-side bescherming hersteld")\n            desired_stage=0\n        middle_ok=(not settings.focus_v2_require_bollinger_middle) or (mid>0 and mark>=mid)\n        equity_context_ok=state.cycle_start_equity<=0 or equity>=state.cycle_start_equity*.85\n        if desired_stage>state.release_stage and short_qty>0 and middle_ok and equity_context_ok:\n            remaining_ratio=recovery_remaining_ratio(desired_stage,settings.focus_v2_release_ratio)\n            target_qty=hedge_target/max(mark,1e-12)\n            desired_short_qty=max(0.0,target_qty*remaining_ratio)\n            q=max(0.0,short_qty-desired_short_qty)\n            if q>0:\n                plan=_plan(client,symbol,mark,q*mark,int(f((short_row or {}).get("leverage"),settings.leverage)))\n                prefix=f"s2fv2-{hashlib.sha256(f'{state.cycle_id}|fastrelease|{desired_stage}'.encode()).hexdigest()[:12]}"\n                result=_close_v2_leg(client=client,plan=plan,side=PositionSide.SHORT,prefix=prefix);cq,cp,_,_=_fill(result)\n                short_entry=f((short_row or {}).get("entryPrice"));realized=(short_entry-cp)*cq;owned=_reduce_owned(owned,ROLE_HEDGE,cq,timestamp_ms)\n                released_total=state.released_short_qty+cq\n                state=replace(state,release_stage=desired_stage,released_short_qty=released_total,realized_hedge_pnl=state.realized_hedge_pnl+realized,last_release_price=cp,last_action=f"RECOVERY_{desired_stage}_RELEASE",last_reason=f"herstelzone {desired_stage}: SHORT tranche vrijgegeven")\n                current_after=max(0.0,short_qty-cq);armed_before=_open_rehedge_qty(open_orders,symbol)\n                allowed_backup=max(0.0,target_qty-current_after-armed_before)\n                backup_qty=min(cq,allowed_backup)\n                sent=1\n                if backup_qty>0:\n                    state=_arm_rehedge(client=client,state=state,settings=settings,mark=cp,quantity=backup_qty,reserve_order=reserve_order);sent+=1\n                ref.set({"focusV2State":state_map(state),"ownedLegs":[owned_to_mapping(x) for x in owned],"focusV2History":{"cycleId":state.cycle_id,"cycleStartEquity":state.cycle_start_equity,"equity":equity,"longNotional":long_notional,"shortNotional":max(0.0,short_notional-cq*cp),"targetShortNotional":hedge_target,"hedgeRatio":max(0.0,short_notional-cq*cp)/long_notional if long_notional>0 else 0.0,"recoveryStage":state.release_stage,"recoveryProgressRatio":progress,"recoveryLow":state.recent_low,"recoveryHigh":state.recovery_high,"longBreakEven":entry,"nextReleasePrice":recovery_stage_price(state.recent_low,entry,min(4,state.release_stage+1)),"nextReleaseQty":max(0.0,(short_qty-cq)-target_qty*recovery_remaining_ratio(min(4,state.release_stage+1),settings.focus_v2_release_ratio)),"releasedShortQty":state.released_short_qty,"armedRehedgeQty":state.armed_rehedge_qty,"rehedgeTrigger":state.rehedge_stop_price,"recoveryModelVersion":state.recovery_model_version,"dcaCount":state.dca_count,"cyclePnl":equity-state.cycle_start_equity}},merge=True)\n                _audit(ref,"FOCUS_V2_FAST_HEDGE_RELEASE",cycleId=state.cycle_id,symbol=symbol,recoveryStage=desired_stage,recoveryProgressRatio=progress,releaseQty=cq,armedRehedgeQty=state.armed_rehedge_qty,rehedgeTrigger=state.rehedge_stop_price,fullRelease=(desired_stage>=4))\n                return {"status":"executed","action":f"FOCUS_V2_RECOVERY_{desired_stage}_RELEASE","symbol":symbol,"ordersSent":sent,"recoveryStage":desired_stage,"recoveryProgressRatio":progress}\n\n'''
text = text[:start] + fast + text[end:]

# Live armed quantity is authoritative for reconciliation and cockpit.
text = text.replace(
    'armed_qty=0.0\n    for o in open_orders or []:\n        if isinstance(o,dict) and str(o.get("symbol","")).upper()==symbol and str(o.get("clientOrderId","")).startswith(REHEDGE_PREFIX):armed_qty+=abs(f(o.get("origQty",o.get("quantity"))))*mark',
    'armed_qty=_open_rehedge_qty(open_orders,symbol)*mark',
)

# Add fast recovery cockpit contract without changing user settings.
hold_anchor = '"shortReleaseRatio":settings.focus_v2_release_ratio,"shortReleaseReady":bool(price_met and middle_met and portfolio_gate_met),'
if hold_anchor in text:
    text = text.replace(hold_anchor, hold_anchor + '"recoveryModelVersion":state.recovery_model_version,"recoveryStage":state.release_stage,"recoveryProgressRatio":state.recovery_progress_ratio,"recoveryLow":state.recent_low,"recoveryHigh":state.recovery_high,"longBreakEven":entry,"nextReleasePrice":state.next_release_price,"releasedShortQty":state.released_short_qty,"armedRehedgeQty":_open_rehedge_qty(open_orders,symbol),"targetShortNotional":hedge_target,"hedgeRatio":short_notional/long_notional if long_notional>0 else 0.0,')

if text == original:
    raise SystemExit("No Focus 2.0 changes applied")
FOCUS.write_text(text, encoding="utf-8")

TEST.parent.mkdir(parents=True, exist_ok=True)
TEST.write_text('''from aster_strategy2_focus_v2 import (\n    RECOVERY_MODEL_FAST, FocusV2State, recovery_progress, recovery_stage_for_progress,\n    recovery_remaining_ratio, state_from, state_map, target_hedge_notional,\n)\n\ndef test_legacy_cycle_defaults_to_old_model():\n    assert state_from({"cycleId":"live-existing"}).recovery_model_version == 1\n\ndef test_new_model_roundtrips_restart_safe_state():\n    s=FocusV2State(cycle_id="x",recovery_model_version=RECOVERY_MODEL_FAST,release_stage=2,released_short_qty=4.2,armed_rehedge_qty=4.2,last_release_price=90,next_release_price=95,recovery_progress_ratio=.51,rehedge_client_ids=("a","b"))\n    assert state_from(state_map(s)) == s\n\ndef test_low_to_break_even_recovery_zones_and_no_tick_repeat_semantics():\n    low,be=80.0,100.0\n    assert recovery_stage_for_progress(recovery_progress(84.3,low,be)) == 0\n    assert recovery_stage_for_progress(recovery_progress(84.4,low,be)) == 1\n    assert recovery_stage_for_progress(recovery_progress(89.6,low,be)) == 2\n    assert recovery_stage_for_progress(recovery_progress(94.4,low,be)) == 3\n    assert recovery_stage_for_progress(recovery_progress(99.0,low,be)) == 4\n    # Re-reading the same progress does not produce a stage > the explicit zone reached.\n    assert recovery_stage_for_progress(recovery_progress(89.6,low,be)) == 2\n\ndef test_release_ratio_is_quantity_not_price_and_progressively_frees_long():\n    r=.33\n    assert recovery_remaining_ratio(1,r) == (1-r)\n    assert recovery_remaining_ratio(2,r) == (1-r)**2\n    assert recovery_remaining_ratio(3,r) == (1-r)**3\n    assert recovery_remaining_ratio(4,r) == 0.0\n\ndef test_large_recoveries_reach_full_release_stage():\n    low,be=80.0,100.0\n    for price in (102,105,110,120,150):\n        assert recovery_stage_for_progress(recovery_progress(price,low,be)) == 4\n\ndef test_hedge_policy_keeps_net_long_bias():\n    target=target_hedge_notional(1000,min_bias_usdt=5,min_bias_ratio=.02,max_hedge_ratio=.95)\n    assert target <= 950\n    assert 1000-target >= 20\n''', encoding="utf-8")

print("Focus 2.0 fast recovery patch applied")
